mapper.select:
SELECT * FROM (
	SELECT ROWNUM rnum, A.* FROM (
		SELECT * 
		FROM SCRAB_USER S
		LEFT OUTER JOIN MEMBER M ON M.USER_ID = S.USER_ID
		LEFT OUTER JOIN RESUME R ON M.RESUME_NO = R.RESUME_NO
		WHERE COMPANY_ID = #{comId}
	    ORDER BY M.MEM_NAME ASC 
  ) A
  WHERE ROWNUM <= #{endRow}
)
WHERE rnum > #{startRow}

SELECT COUNT(*)
FROM SCRAB_USER S
WHERE COMPANY_ID = #{comId}

SELECT * FROM (
  SELECT ROWNUM rnum, A.* FROM (
    SELECT R.*
    FROM RESUME R
    JOIN MEMBER M ON M.RESUME_NO = R.RESUME_NO
    WHERE 1=1
      AND M.RESUME_NO IS NOT NULL


        AND EXISTS (
          SELECT 1 FROM CAREER C
          WHERE C.RESUME_NO = R.RESUME_NO
          AND C.JOB_CODE IN

            #{job}


            AND C.CAREER_YEAR >= #{careerYearMin}


            AND C.CAREER_YEAR <= #{careerYearMax}


            AND C.POSITION_GRADE_CODE IN

              #{grade}


        )



        AND (
          SELECT COUNT(DISTINCT L.LICENSE_CODE)
          FROM MY_LICENSE L
          WHERE L.RESUME_NO = R.RESUME_NO
          AND L.LICENSE_CODE IN

            #{code}

        ) = ${licenseCodeList.size()}



        AND (
          SELECT COUNT(DISTINCT S.MY_SKILL_CODE)
          FROM MY_SKILL S
          WHERE S.RESUME_NO = R.RESUME_NO
          AND UPPER(S.MY_SKILL_NAME) IN

             UPPER(#{code})

        ) = ${skillCodeList.size()}



        AND EXISTS (
          SELECT 1 FROM LANGUAGE_SKILL LS
          WHERE LS.RESUME_NO = R.RESUME_NO
          AND LS.LANGUAGE_EXAM_NAME = #{languageName}
          AND LS.LANGUAGE_EXAM_SCORE >= #{languageScoreMin}
        )



        AND EXISTS (
          SELECT 1 FROM EDUCATION E
          WHERE E.RESUME_NO = R.RESUME_NO
          AND E.HIGHEST_EDUCATION_CODE = #{educationCode}
        )


        AND EXISTS (
          SELECT 1 FROM SPECIALTY S
          WHERE S.RESUME_NO = R.RESUME_NO
          AND (S.MAIN_MAJOR LIKE '%' || #{majorName} || '%' OR S.SUB_MAJOR LIKE '%' || #{majorName} || '%')
        )


		  AND (


		      NOT EXISTS (
		        SELECT 1 FROM CAREER C
		        WHERE C.RESUME_NO = R.RESUME_NO
		      )



		      (
		        NOT EXISTS (
		          SELECT 1 FROM CAREER C
		          WHERE C.RESUME_NO = R.RESUME_NO
		        )
		        OR
		        EXISTS (
		          SELECT 1 FROM CAREER C
		          WHERE C.RESUME_NO = R.RESUME_NO
		          AND C.CAREER_YEAR IN

		            #{year}

		        )
		      )



		      EXISTS (
		        SELECT 1 FROM CAREER C
		        WHERE C.RESUME_NO = R.RESUME_NO
		        AND C.CAREER_YEAR IN

		          #{year}

		      )

		  )

    ORDER BY R.RESUME_NO DESC  
  ) A
  WHERE ROWNUM <= #{endRow}
)
WHERE rnum > #{startRow}

SELECT LICENSE_CODE
	, (SELECT C.CODE_NAME FROM CMN_CODE C WHERE C.CODE_DETAIL_NO = LICENSE_CODE) AS LICENSE_CODE_NAME
FROM MY_LICENSE WHERE RESUME_NO = #{resumeNo}

	SELECT COUNT(*)
	FROM RESUME R
	JOIN MEMBER M ON M.RESUME_NO = R.RESUME_NO
	WHERE 1=1
      AND M.RESUME_NO IS NOT NULL


        AND EXISTS (
          SELECT 1 FROM CAREER C
          WHERE C.RESUME_NO = R.RESUME_NO
          AND C.JOB_CODE IN

            #{job}


            AND C.CAREER_YEAR >= #{careerYearMin}


            AND C.CAREER_YEAR <= #{careerYearMax}


            AND C.POSITION_GRADE_CODE IN

              #{grade}


        )



        AND (
          SELECT COUNT(DISTINCT L.LICENSE_CODE)
          FROM MY_LICENSE L
          WHERE L.RESUME_NO = R.RESUME_NO
          AND L.LICENSE_CODE IN

            #{code}

        ) = ${licenseCodeList.size()}



        AND (
          SELECT COUNT(DISTINCT S.MY_SKILL_CODE)
          FROM MY_SKILL S
          WHERE S.RESUME_NO = R.RESUME_NO
          AND UPPER(S.MY_SKILL_NAME) IN

             UPPER(#{code})

        ) = ${skillCodeList.size()}



        AND EXISTS (
          SELECT 1 FROM LANGUAGE_SKILL LS
          WHERE LS.RESUME_NO = R.RESUME_NO
          AND LS.LANGUAGE_EXAM_NAME = #{languageName}
          AND LS.LANGUAGE_EXAM_SCORE >= #{languageScoreMin}
        )



        AND EXISTS (
          SELECT 1 FROM EDUCATION E
          WHERE E.RESUME_NO = R.RESUME_NO
          AND E.HIGHEST_EDUCATION_CODE = #{educationCode}
        )


        AND EXISTS (
          SELECT 1 FROM SPECIALTY S
          WHERE S.RESUME_NO = R.RESUME_NO
          AND (S.MAIN_MAJOR LIKE '%' || #{majorName} || '%' OR S.SUB_MAJOR LIKE '%' || #{majorName} || '%')
        )


		  AND (


		      NOT EXISTS (
		        SELECT 1 FROM CAREER C
		        WHERE C.RESUME_NO = R.RESUME_NO
		      )



		      (
		        NOT EXISTS (
		          SELECT 1 FROM CAREER C
		          WHERE C.RESUME_NO = R.RESUME_NO
		        )
		        OR
		        EXISTS (
		          SELECT 1 FROM CAREER C
		          WHERE C.RESUME_NO = R.RESUME_NO
		          AND C.CAREER_YEAR IN

		            #{year}

		        )
		      )



		      EXISTS (
		        SELECT 1 FROM CAREER C
		        WHERE C.RESUME_NO = R.RESUME_NO
		        AND C.CAREER_YEAR IN

		          #{year}

		      )

		  )

    ORDER BY R.RESUME_NO DESC
